const BASE = 'https://api.lokalise.com/api2';
const PID = '31393214664f295f94dd86.76792605';
const MT_TO_REVIEW = 29251;
const DATA = [
  {id: 866733814, t: "Der König"},
  {id: 866733817, t: "Der Krieger"},
  {id: 866733820, t: "Der Liebende"},
  {id: 866733823, t: "Der Weise"},
  {id: 866733826, t: "Der Rebell"},
  {id: 866733829, t: "Der Versorger"},
  {id: 866733832, t: "Der Entdecker"},
  {id: 866733835, t: "Der Handwerker"},
  {id: 866734035, t: "Emotionale Intensität steuern"},
  {id: 866734041, t: "Grenzen stärken"},
  {id: 866734047, t: "Strategisches Bewusstsein entwickeln"},
  {id: 866734144, t: "Beständigkeit stärken"},
  {id: 866734036, t: "Weil du emotional feinfühlig bist, kann dir Folgendes helfen:"},
  {id: 866734040, t: "So vermeidest du Überforderung."},
  {id: 866734042, t: "Du musst deine Empathie nicht zurücknehmen – aber du kannst Folgendes tun:"},
  {id: 866734046, t: "Das schafft Balance."},
  {id: 866734037, t: "Raum schaffen, um Erlebnisse zu verarbeiten"},
  {id: 866734038, t: "Die Emotionen anderer nicht zu stark aufnehmen"},
  {id: 866734039, t: "Emotionale Grenzen wahren"},
  {id: 866734043, t: "Schütze deine Zeit und Energie"},
  {id: 866734044, t: "Übernimm keine unnötige Verantwortung"},
  {id: 866734045, t: "Erkenne, wo deine Rolle endet"}
];
const payload = { keys: DATA.map(d => ({
  key_id: d.id,
  translations: [{
    language_iso: 'de',
    translation: d.t,
    is_reviewed: false,
    is_fuzzy: true,
    custom_translation_status_ids: [MT_TO_REVIEW]
  }]
})) };
return [{ json: { url: BASE + '/projects/' + PID + '/keys', payload: payload, count: DATA.length, ids: DATA.map(d => d.id) } }];

const r = $input.first().json || {};
const b = r.body !== undefined ? r.body : r;
const cfg = $('Build payload').first().json;
const keys = Array.isArray(b.keys) ? b.keys : [];
const errs = Array.isArray(b.errors) ? b.errors : [];
const written = [];
for (const k of keys) {
  for (const t of (k.translations || [])) {
    if (t.language_iso !== 'de') continue;
    written.push({ key_id: k.key_id, translation: t.translation,
      is_fuzzy: t.is_fuzzy, is_reviewed: t.is_reviewed,
      statuses: (t.custom_translation_statuses || []).map(s => s.status_id + ':' + s.title) });
  }
}
return [{ json: {
  statusCode: r.statusCode,
  requested: cfg.count,
  keys_returned: keys.length,
  de_translations_written: written.length,
  api_errors: errs,
  raw_error: keys.length ? null : JSON.stringify(b).slice(0, 600),
  written: written
} }];
